import assert from 'node:assert/strict';
import { describe, it } from 'node:test';
import { restaurantsMock } from '../../mocks/restaurants.mock.ts';
import {
  getRestaurantOrderRestriction,
  ORDER_ERROR_FADE_DELAY_MS,
  ORDER_ERROR_FADE_DURATION_MS,
  ORDER_RESTRICTION_CODE,
} from '../../app/customer/restaurantOrderRules.ts';

describe('R-ORD-02 - ORD restaurant order restriction', () => {
  it('allows an open restaurant without showing a restriction', () => {
    assert.equal(getRestaurantOrderRestriction(restaurantsMock[0]), null);
  });

  it('returns the requirement code and message for a paused restaurant', () => {
    const restriction = getRestaurantOrderRestriction({
      ...restaurantsMock[0],
      status: 'paused',
    });

    assert.deepEqual(restriction, {
      code: 'R-ORD-02 - ORD',
      message: 'Orders are unavailable at Maple & Main because it is paused.',
    });
    assert.equal(restriction?.code, ORDER_RESTRICTION_CODE);
  });

  it('returns the requirement code and message for a closed restaurant', () => {
    const restriction = getRestaurantOrderRestriction({
      ...restaurantsMock[0],
      status: 'closed',
    });

    assert.deepEqual(restriction, {
      code: 'R-ORD-02 - ORD',
      message: 'Orders are unavailable at Maple & Main because it is closed.',
    });
  });

  it('configures the alert to disappear after two seconds total', () => {
    assert.equal(ORDER_ERROR_FADE_DELAY_MS + ORDER_ERROR_FADE_DURATION_MS, 2000);
  });
});
